import { createServerFileRoute } from '@tanstack/react-start/server'
import { json } from '@tanstack/react-start'
import { posts } from '../../db'

export const ServerRoute = createServerFileRoute('/api/posts/$id/like').methods({
  POST: async ({ request, params }) => {
    const { id } = params

    let body: { fail?: boolean } = {}
    try {
      body = await request.json()
    } catch (e) {
      // Ignore parsing errors or empty body
    }

    if (body && body.fail === true) {
      return new Response(JSON.stringify({ error: 'Simulated failure' }), {
        status: 500,
        headers: { 'Content-Type': 'application/json' },
      })
    }

    const post = posts.find((p) => p.id === id)
    if (!post) {
      return new Response(JSON.stringify({ error: 'Post not found' }), {
        status: 404,
        headers: { 'Content-Type': 'application/json' },
      })
    }

    post.likes += 1
    return json(post)
  }
})

